type Instruction = { op: "move"; x: number; z: number } | { op: "place"; block: BlockId };
function run(program: Instruction[]): void {
  for (const ins of program) {
    if (ins.op === "move") golem.moveTo(ins.x, ins.z);
    else golem.place(ins.block, 0, 64, 0);
  }
}

